css:
.dcx{ -webkit-text-size-adjust: 100%; }
.dcx{ margin: 0; background: #fff; color: #08120D; font-family: 'Instrument Sans', system-ui, sans-serif; -webkit-font-smoothing: antialiased; overflow-x:clip; }
.dcx *{ box-sizing: border-box; }
.dcx h1,.dcx h2,.dcx h3,.dcx h4{ margin: 0; font-family: 'Source Serif 4', Georgia, serif; font-weight: 700; letter-spacing: -0.015em; }
.dcx p{ margin: 0; text-wrap: pretty; }
.dcx a{ color: #0B7A45; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; border-radius: 4px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover,.dcx [data-navitem]:focus-within [data-mega]{ display: block; }
.dcx [data-nav-toggle]{ display: none; }
@media (max-width: 1180px){.dcx [data-nav-links],.dcx [data-nav-lang],.dcx [data-nav-login]{ display: none !important; }
.dcx [data-nav-toggle]{ display: grid !important; }
.dcx [data-nav-sheet][data-open="1"]{ display: block !important; }
.dcx [data-hero],.dcx [data-feat],.dcx [data-news],.dcx [data-quote]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-latest]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-topics]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-videos],.dcx [data-support]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-pills]{ position: static !important; margin: 18px 0 0 !important; }
.dcx [data-ctaimg]{ display: none !important; }
}
@media (max-width: 760px){.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
.dcx [data-latest]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-topics],.dcx [data-vidgrid]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 38px !important; }
.dcx [data-h2]{ font-size: 26px !important; }
}
